K="kubectl"
c() { echo "===SHELLPILOT-$1==="; shift; $K "$@" 2>&1; }
c NODES get nodes --no-headers -o 'custom-columns=NAME:.metadata.name,MEM:.status.conditions[?(@.type=="MemoryPressure")].status,DISK:.status.conditions[?(@.type=="DiskPressure")].status,PID:.status.conditions[?(@.type=="PIDPressure")].status,READY:.status.conditions[?(@.type=="Ready")].status,CPU:.status.allocatable.cpu,MEM2:.status.allocatable.memory,PODS:.status.allocatable.pods,TAINTS:.spec.taints[*].key'
c WORKLOADRES get deployments -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,REPLICAS:.spec.replicas,CPUREQ:.spec.template.spec.containers[*].resources.requests.cpu,MEMREQ:.spec.template.spec.containers[*].resources.requests.memory,CPULIM:.spec.template.spec.containers[*].resources.limits.cpu,MEMLIM:.spec.template.spec.containers[*].resources.limits.memory'
echo "===SHELLPILOT-WORKLOADLABELS==="; kubectl get deployments -A -o go-template='{{range .items}}{{.metadata.namespace}}|{{.metadata.name}}|{{.spec.replicas}}|{{range $k,$v := .spec.selector.matchLabels}}{{$k}}={{$v}};{{end}}{{"\n"}}{{end}}' 2>&1
c HPA get hpa -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,TARGET:.spec.scaleTargetRef.name,MIN:.spec.minReplicas,MAX:.spec.maxReplicas,CUR:.status.currentReplicas,DES:.status.desiredReplicas,TU:.spec.metrics[0].resource.target.averageUtilization,CU:.status.currentMetrics[0].resource.current.averageUtilization'
echo "===SHELLPILOT-PDB==="; kubectl get poddisruptionbudgets --all-namespaces -o 'jsonpath={range .items[*]}{.metadata.namespace}{"|"}{.metadata.name}{"|"}{.status.disruptionsAllowed}{"|"}{.status.currentHealthy}{"|"}{.status.desiredHealthy}{"|"}{.status.expectedPods}{"|"}{.spec.selector.matchLabels}{"|"}{.spec.selector.matchExpressions}{"\n"}{end}' 2>&1
c STALEPODS get pods -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,PHASE:.status.phase,REASON:.status.reason,START:.status.startTime,OWNER:.metadata.ownerReferences[0].kind'
c STALEJOBS get jobs -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,SUCCEEDED:.status.succeeded,FAILED:.status.failed,START:.status.startTime,DONE:.status.completionTime'
c PV get pv --no-headers -o 'custom-columns=NAME:.metadata.name,CAP:.spec.capacity.storage,RECLAIM:.spec.persistentVolumeReclaimPolicy,STATUS:.status.phase,CNS:.spec.claimRef.namespace,CNAME:.spec.claimRef.name,SC:.spec.storageClassName,REASON:.status.reason'
c DS get ds -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,DESIRED:.status.desiredNumberScheduled,CURRENT:.status.currentNumberScheduled,READY:.status.numberReady,UPTODATE:.status.updatedNumberScheduled,AVAIL:.status.numberAvailable,UNAVAIL:.status.numberUnavailable,MISSCHED:.status.numberMisscheduled,GEN:.metadata.generation,OBSGEN:.status.observedGeneration'
c WARN get events -A --field-selector type=Warning --no-headers -o 'custom-columns=NS:.metadata.namespace,REASON:.reason,KIND:.involvedObject.kind,NAME:.involvedObject.name,COUNT:.count,LAST:.lastTimestamp,MSG:.message'
c CM get cm -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,AGE:.metadata.creationTimestamp'
c PVCX get pvc -A --no-headers -o 'custom-columns=NS:.metadata.namespace,NAME:.metadata.name,PHASE:.status.phase,AGE:.metadata.creationTimestamp'
echo "===SHELLPILOT-REFS==="
kubectl get pods -A -o 'jsonpath={range .items[*]}{.metadata.namespace}{"|"}{.metadata.name}{"|cm:"}{range .spec.volumes[*]}{.configMap.name}{";"}{range .projected.sources[*]}{.configMap.name}{";"}{end}{end}{"|env:"}{range .spec.containers[*]}{range .envFrom[*]}{.configMapRef.name}{";"}{end}{range .env[*]}{.valueFrom.configMapKeyRef.name}{";"}{end}{end}{"|pvc:"}{range .spec.volumes[*]}{.persistentVolumeClaim.claimName}{";"}{end}{"\n"}{end}' 2>&1
